def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        t = op[1]

        # Remove expired entries
        expired_keys = []
        for key, (value, write_time) in cache.items():
            if write_time + ttl <= t:
                expired_keys.append(key)
        for key in expired_keys:
            del cache[key]

        if op[0] == 'put':
            key, value = op[2], op[3]

            # Remove key if it exists (to re-add it as most recent)
            if key in cache:
                del cache[key]

            # Evict LRU if at capacity
            if len(cache) >= capacity:
                cache.popitem(last=False)  # Remove oldest (least recently used)

            # Add the new entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

